\subsection{Definitions and mathematical statement}
\paragraph{Statement recorded in the supplied source.}
For every $n\geq 1$ and recursively enumerable $S\subset N^{n}$, do there exist $m\geq 1$ and $P\in Z[A_{1},\dots ,A_{n},W_{1},\dots ,W_m]$ such that each $a\in S$ has exactly one tuple $w\in N^m$ with $P(a,w)=0$ and each $a\notin S$ has none?

\subsection{Short English statement}
For every $n\geq 1$ and recursively enumerable $S\subset N^{n}$, do there exist $m\geq 1$ and $P\in Z[A_{1},\dots ,A_{n},W_{1},\dots ,W_m]$ such that each $a\in S$ has exactly one tuple $w\in N^m$ with $P(a,w)=0$ and each $a\notin S$ has none?

\subsection{Sources}
\begin{itemize}
\item[S1] Original question source or mathematical context.
\url{https://www.mathnet.ru/eng/znsl3816}.
\item[S2] OpenAI, manuscript citation page. Source of the formulation motivating this local problem.
\url{https://github.com/openai/math/blob/adc7f1241b42e322a6451854ab7e4b4c146bf78a/preprints/Single-fold-Diophantine-representations-September-24-2026/README.md}.
\end{itemize}

